def _get_workplan(plan) -> object:
    """Extract workplan from plan or strategy, returning None if unavailable."""
    workplan = getattr(plan, 'workplan', None)
    if not workplan:
        strategy = getattr(plan, 'strategy', None)
        if strategy:
            workplan = getattr(strategy, 'parallelisable_workplan', None)
    return workplan


def _collect_tasks(groups: list) -> list:
    """Flatten tasks from all groups, handling None groups safely."""
    tasks: list = []
    for group in groups or []:
        tasks.extend(getattr(group, 'tasks', []) or [])
    return tasks


def _validate_task_files(tasks: list) -> list[str]:
    """Check that each task has exactly 1 file and no file collisions."""
    violations: list[str] = []
    seen: set[str] = set()
    for task in tasks:
        fps = getattr(task, 'file_paths', None) or []
        if len(fps) != 1:
            violations.append(
                f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)"
            )
        for fp in fps:
            if fp in seen:
                violations.append(f'file collision: {fp} in multiple tasks')
            seen.add(fp)
    return violations"}

